const S = {"C": {"type": "object", "properties": {"checks": {"type": "array", "items": {"type": "string"}}}, "required": ["checks"]}, "ALT": {"type": "object", "properties": {"poems": {"type": "array", "items": {"type": "string"}}, "note": {"type": "string"}}, "required": ["poems", "note"]}, "P": {"type": "object", "properties": {"poem": {"type": "string"}, "lib_calls": {"type": "integer"}}, "required": ["poem", "lib_calls"]}}
